#!/usr/bin/env python3
"""Apply script: reweight scorecard when claims unavailable, retune zone/industry
weights, add Portfolio Analysis reference to the scorecard.

Run from the HealthCross repo root: python3 apply_scorecard_reweight_and_portfolio_reference.py
IMPORTANT: this only changes the SEEDED defaults for a fresh/untouched (version 1)
weight set. Your live active weight set may already be past version 1 (e.g. from a
prior recalibration), in which case this alone will NOT change its actual numbers -
run set_scoring_weights_v2.py (sent alongside this) once afterward to force-apply
the new demographic/claims/benefits/industry weights and zone multipliers directly.
"""
import base64, hashlib, os, sys

MARKER = "SCORECARD_REWEIGHT_PORTFOLIO_REFERENCE_2026_08_05"

FILES = [
    {
        'path': 'app/api/routes_scoring.py',
        'sha256': '0b697d38d96bdc9f49e1f2e15100c9d0d87af7801acc63819990e56cf711b5e9',
        'size': 8488,
        'b64': '',
    },
    {
        'path': 'app/main.py',
        'sha256': '62f63e8ab1c56b37c6b5c92a39740c65c739a7480de85b311f6c687cfe97e570',
        'size': 6229,
        'b64': '',
    },
    {
        'path': 'app/scoring/engine.py',
        'sha256': '52303085bfa5b46290a44b5930a69a48b2ce1d733f35e9bf1b5fdd57e223aaeb',
        'size': 7413,
        'b64': '',
    },
    {
        'path': 'app/scoring/rules/portfolio_analysis.py',
        'sha256': '6a1d68da2a99a961169d177e6f20b4279644215d2a3a5ae71b03dcacc450842f',
        'size': 26354,
        'b64': '',
    },
    {
        'path': 'app/static/index.html',
        'sha256': '73d2d468f04ebd757e7301fd6e9e0f3378c71525ed6fd4c884544cb8a7e36504',
        'size': 161842,
        'b64': '',
    },
    {
        'path': 'tests/test_main_seeding.py',
        'sha256': '188f4499a69c76b5ef53e6935147a94831c2a9335180c88d0174e7ade5c3e0c2',
        'size': 5515,
        'b64': '',
    },
    {
        'path': 'tests/test_portfolio_analysis.py',
        'sha256': 'a2428cbf0a014859758b96f5cf04e66f0b7c5c6256abe7bd24d0d0b3d4cbc6de',
        'size': 35431,
        'b64': '',
    },
    {
        'path': 'tests/test_scoring_engine.py',
        'sha256': 'a6fd26536bcaad281f1508c1d32f3c570ca0bfebf2114c787351851b835848de',
        'size': 6381,
        'b64': '',
    },
    {
        'path': 'tests/test_api_scoring_portfolio_reference.py',
        'sha256': '0510238c36d8c4d86816f015426a51d404281269fd5a2b3becc505f5c7f45433',
        'size': 7639,
        'b64': '',
    },
]


def main():
    repo_root = os.getcwd()
    ok = True
    for entry in FILES:
        path = os.path.join(repo_root, entry['path'])
        data = base64.b64decode(entry['b64'])
        if len(data) != entry['size']:
            print(f"SIZE MISMATCH before write: {entry['path']}")
            ok = False
            continue
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as f:
            f.write(data)
        with open(path, 'rb') as f:
            written = f.read()
        actual_sha = hashlib.sha256(written).hexdigest()
        if actual_sha == entry['sha256']:
            print(f"OK  {entry['path']}  ({len(written)} bytes, sha256={actual_sha[:12]}...)")
        else:
            print(f"CHECKSUM MISMATCH  {entry['path']}  expected={entry['sha256'][:12]}... actual={actual_sha[:12]}...")
            ok = False
    if ok:
        print(f"\nAll files written and verified. Marker: {MARKER}")
        print("Next: python3 -m pytest -q   (should show 494 passed)")
        print("Then: run python3 set_scoring_weights_v2.py to force-apply the new weight numbers")
        print("      to your live active weight set (see that script's own docstring).")
        print("Then: git add -A && git commit -m '...' && git push")
    else:
        print("\nSOME FILES FAILED TO VERIFY - do not commit. Re-run this script once more first.")
        sys.exit(1)


if __name__ == '__main__':
    main()
